@pytest.mark.pre_alloc_mutable
def test_jump(
    state_test: StateTestFiller,
    pre: Alloc,
    tx_data_hex: str,
    expected_post: dict,
) -> None:
    """Ori Pomerantz qbzzt1@gmail.com."""
    coinbase = Address("0x2adc25665018aa1fe0e6bc666dac8fc2697ff9ba")
    sender = Address("0xa94f5374fce5edbc8e2a8697c15331677e6ebf0b")
    contract = Address("0xcccccccccccccccccccccccccccccccccccccccc")
    callee = Address("0x0000000000000000000000000000000000001000")
    callee_1 = Address("0x0000000000000000000000000000000000001001")
    callee_2 = Address("0x0000000000000000000000000000000000001002")
    callee_3 = Address("0x0000000000000000000000000000000000001003")
    callee_4 = Address("0x0000000000000000000000000000000000001004")
    callee_5 = Address("0x0000000000000000000000000000000000001005")
    callee_6 = Address("0x0000000000000000000000000000000000001006")
    callee_7 = Address("0x0000000000000000000000000000000000001007")
    callee_8 = Address("0x0000000000000000000000000000000000001008")
    callee_9 = Address("0x0000000000000000000000000000000000001009")
    callee_10 = Address("0x000000000000000000000000000000000000100a")
    callee_11 = Address("0x000000000000000000000000000000000000100b")
    callee_12 = Address("0x000000000000000000000000000000000000100c")
    callee_13 = Address("0x000000000000000000000000000000000000100d")
    callee_14 = Address("0x000000000000000000000000000000000000100e")
    callee_15 = Address("0x000000000000000000000000000000000000100f")
    callee_16 = Address("0x0000000000000000000000000000000000001010")

    env = Environment(
        fee_recipient=coinbase,
        number=1,
        timestamp=1000,
        prev_randao=0x20000,
        base_fee_per_gas=10,
        gas_limit=100000000,
    )

    pre[callee] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=(
        Op.SSTORE(key=0x0, value=0x600d) + Op.JUMP(pc=Op.MUL(0x20, 0x10))
        + Op.JUMPDEST + Op.STOP
    ),
    )
    pre[callee_1] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=(
        Op.SSTORE(key=0x0, value=0x600d)
        + Op.JUMPI(pc=Op.MUL(0x20, 0x10), condition=0x1) + Op.JUMPDEST + Op.STOP
    ),
    )
    pre[callee_2] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=(
        Op.JUMP(pc=0x4) + Op.STOP + Op.JUMPDEST + Op.SSTORE(key=0x0, value=0x600d)
        + Op.STOP
    ),
    )
    pre[callee_3] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=Op.SSTORE(key=0x0, value=0x600d) + Op.JUMP(pc=0xfffffff) + Op.STOP,
    )
    pre[callee_4] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=(
        Op.PUSH1[0x23] + Op.JUMP(pc=0x8) + Op.PUSH1[0x1] + Op.JUMPDEST
        + Op.PUSH1[0x2] + Op.SSTORE
    ),
    )
    pre[callee_5] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=Op.SSTORE(key=0x0, value=0x600d) + Op.JUMPDEST + Op.JUMP(pc=0x6),
    )
    pre[callee_6] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=(
        Op.PUSH2[0x600d] + Op.JUMP(pc=0x8) + Op.PUSH1[0xff] + Op.JUMPDEST
        + Op.PUSH1[0x0] + Op.SSTORE
    ),
    )
    pre[callee_7] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=(
        Op.JUMP(pc=0xb) + Op.JUMPDEST + Op.SSTORE(key=0x0, value=0x600d) + Op.STOP
        + Op.JUMPDEST + Op.JUMP(pc=0x3)
    ),
    )
    pre[callee_8] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=(
        Op.JUMP(pc=Op.ADD(0x5, 0x2)) + Op.STOP + Op.JUMPDEST
        + Op.SSTORE(key=0x0, value=0x600d)
    ),
    )
    pre[callee_9] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=Op.JUMP(pc=0x5) + Op.STOP + Op.PUSH1[0x5b] + Op.SSTORE(key=0x0, value=0x600d),
    )
    pre[callee_10] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=Op.JUMP(pc=0x5) + Op.STOP + Op.PUSH1[0x1] + Op.SSTORE(key=0x0, value=0x600d),
    )
    pre[callee_11] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=(
        Op.SSTORE(key=0x0, value=0x600d) + Op.JUMP(pc=0xb) + Op.GAS + Op.JUMPDEST
        + Op.SSTORE(key=0x1, value=Op.GAS)
    ),
    )
    pre[callee_12] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=(
        Op.SSTORE(key=0x0, value=0x600d) + Op.JUMP(pc=0x9) + Op.GAS + Op.JUMPDEST
        + Op.SSTORE(key=0x1, value=Op.GAS)
    ),
    )
    pre[callee_13] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=(
        Op.JUMP(pc=0x1000000000000000b) + Op.JUMPDEST + Op.JUMPDEST
        + Op.SSTORE(key=0x1, value=0x1)
    ),
    )
    pre[callee_14] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=(
        Op.JUMP(pc=0x100000007) + Op.JUMPDEST + Op.JUMPDEST
        + Op.SSTORE(key=0x1, value=0x1)
    ),
    )
    pre[callee_15] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=(
        Op.POP(Op.MLOAD(offset=0x0)) + Op.POP(Op.SUB(0x0, 0x1))
        + Op.JUMP(pc=Op.MLOAD(offset=0x0)) + Op.SSTORE(key=0x0, value=0x600d)
        + Op.STOP
    ),
    )
    pre[callee_16] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=(
        Op.JUMP(pc=0xe) + Op.JUMPDEST + Op.JUMPDEST + Op.JUMPDEST + Op.JUMPDEST
        + Op.JUMPDEST + Op.JUMPDEST + Op.JUMPDEST + Op.JUMPDEST + Op.JUMPDEST
        + Op.JUMPDEST + Op.JUMPDEST + Op.JUMPDEST + Op.JUMPDEST + Op.JUMPDEST
        + Op.JUMPDEST + Op.JUMPDEST + Op.SSTORE(key=0x0, value=0x600d)
    ),
    )
    pre[sender] = Account(balance=0x100000000000, nonce=0)
    pre[contract] = Account(
        balance=0xba1a9ce0ba1a9ce,
        nonce=0,
        code=(
        Op.DELEGATECALL(gas=0x10000, address=Op.ADD(0x1000, Op.CALLDATALOAD(offset=0x4)), args_offset=0x0, args_size=0x0, ret_offset=0x0, ret_size=0x0)
        + Op.STOP
    ),
        storage={0x0: 0xbad},
    )

    tx_data = bytes.fromhex(tx_data_hex) if tx_data_hex else b""

    tx = Transaction(
        secret_key=Hash(
            "0x45a915e4d060149eb4365960e6a7a45f334393093061116b197e3240065ff2d8"
        ),
        to=contract,
        data=tx_data,
        gas_limit=16777216,
        gas_price=10,
        nonce=0,
        value=1,
    )

    post = expected_post

    state_test(env=env, pre=pre, post=post, tx=tx)
